todo.code:
let todos = state([]);
let text = state('');
div(
    input({ oninput: e => text.value = e.target.value }),
    button('Add', { onclick: () => { todos.value = [...todos.value, text.value]; text.value = ''; } }),
    ul(() => todos.value.map(t => li(t)))
);

form.code:
let formState = state({ email: '', pass: '' });
form({ onsubmit: e => { e.preventDefault(); } },
    input({ oninput: e => formState.value = { ...formState.value, email: e.target.value } }),
    button('Submit', { type: 'submit' })
);
